 id:'approaches',number:'08',title:'Predictive, adaptive & hybrid',subtitle:'Fit the way of working to the uncertainty.',minutes:17,icon:'→ ↻ ⇄',lectures:['Project Management Approaches'],terms:['Predictive','Adaptive','Hybrid','Iterative','Incremental'],sources:['toc8','pmi8','eco26'],reference:'Guide §3 tailoring; original delivery examples',
 objectives:['Compare planning and feedback patterns.','Separate iterative improvement from incremental delivery.','Explain a hybrid choice using context.'],
