export const QUESTIONS = LESSONS.flatMap(l=>[l.pre,l.recallQ,l.lab,l.decision,...l.exam].map(q=>({...q,lessonId:l.id,sourceIds:l.sources,provenance:'Original practice · not an official PMI exam item'})));
export const QUESTION_MAP=Object.fromEntries(QUESTIONS.map(q=>[q.id,q]));
